import {createRequire} from 'node:module';import fs from 'node:fs/promises';import assert from 'node:assert/strict';import crypto from 'node:crypto';
const {chromium}=createRequire(import.meta.url)(process.env.PLAYWRIGHT_MODULE||'playwright');
const base='https://zhongkao.pinmooconsulting.com',dir='guangzhou-zhongkao/docs/deploy-20261005-2100';await fs.mkdir(dir,{recursive:true});
const browser=await chromium.launch({headless:true});const page=await browser.newPage({viewport:{width:1440,height:1000}}),checks=[],errors=[];page.on('pageerror',e=>errors.push(e.message));
try{
 for(const file of ['index.html','app.js','site-shell.js','dynamic-ui.js','motion-theme.css','form-layout.js','school-service.js','workflow-ui.js','data/manifest.json','data/allocations-2026.json','assets/family-planning-20261005.webp','verify/index.html','unlock/index.html']){const response=await page.request.get(`${base}/${file==='index.html'?'':file}`);assert.equal(response.status(),200,file);const actual=crypto.createHash('sha256').update(await response.body()).digest('hex'),expected=crypto.createHash('sha256').update(await fs.readFile(`dist/zhongkao/${file}`)).digest('hex');assert.equal(actual,expected,file);checks.push({file,status:200,sha256:actual});}
 await page.goto(base);await page.locator('.launch-hero').waitFor();assert.ok(await page.locator('.launch-art img').evaluate(el=>el.complete&&el.naturalWidth>0));await page.screenshot({path:`dir/home-live.png`.replace('dir/',`${dir}/`)});
 const health=await page.request.get(`${base}/api/access/health`);assert.equal((await health.json()).ok,true);const session=await page.request.get(`${base}/api/access/session`);const anonymous=await session.json();assert.equal(Boolean(anonymous.entitled),false);
 checks.push({check:'live anonymous serial gate and service',status:'passed'});
 await page.goto(`${base}/unlock/`);await page.locator('#serialCode').waitFor({state:'attached'}).catch(()=>page.locator('input').first().waitFor({state:'attached'}));
 // Verify the deployed UI with an isolated entitlement fixture; no activation or device binding.
 await page.route('**/api/access/session',r=>r.fulfill({json:{authenticated:true,entitled:true,accessSource:'serial',serial:{deviceCount:1,maxDevices:2,remainingDevices:1}}}));
 await page.goto(`${base}/verify/?new=1`);await page.waitForFunction(()=>document.body.dataset.uiReady==='true',null,{timeout:60000});await page.locator('#scoreLow').fill('680');await page.locator('#scoreHigh').fill('700');await page.locator('#scoreHigh').dispatchEvent('change');await page.locator('#generateUnified').click();await page.waitForFunction(()=>!document.getElementById('generateUnified').disabled);assert.equal(await page.locator('#analysis').isVisible(),false);assert.equal(await page.locator('[data-flow-step="plan"]').evaluate(el=>el.classList.contains('active')),true);await page.locator('#volunteerForm').scrollIntoViewIfNeeded();await page.screenshot({path:`${dir}/step2-live.png`});await page.locator('#analyzePlan').click();await page.locator('#analysis[data-stale="false"]').waitFor({state:'visible',timeout:60000});assert.notEqual(await page.locator('#totalScore').innerText(),'--');await page.locator('[data-school-detail]').first().click();await page.locator('#quickSchoolPreview .preview-actions').waitFor({timeout:60000});checks.push({check:'live step 2 confirmation, step 3 evaluation and school preview',status:'passed',access:'isolated entitlement fixture; not a real serial activation'});
 assert.deepEqual(errors,[]);await fs.writeFile(`${dir}/receipt.json`,JSON.stringify({status:'published-and-verified',origin:base,release:'ui-20261005-2100',previousRelease:'20260726-school-details-nav',checkedAt:new Date().toISOString(),checks,errors,activation:'real serial activation not performed; live service and anonymous gate checked'},null,2));console.log(JSON.stringify({status:'published-and-verified',checks:checks.length,errors}));
}finally{await browser.close();}
